{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "At the start of stage 1, how many tools do you have on hand?",
    "Are any of them broken (i.e., already in repair or needing repair)?"
  ],
  "rationale": "The response asks for two distinct pieces of information: the total count of tools and the status of those tools regarding damage/repair. A user could answer the count without specifying which are broken, or vice versa."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since the initial inventory is still being confirmed internally, should I model the starting inventory as a parameter (say, I_0 working tools and B_0 broken tools at the start of stage 1) that you can fill in later, or would you prefer I assume a specific default such as zero tools on hand at the start?"
  ],
  "rationale": "The response asks for a single policy choice regarding how to handle the initial inventory (parameter vs. default), which constitutes one semantically independent question."
}

